import {modules,permissionLabels} from "@/domains/modules/registry";
import {moduleDoc,type DocMeta} from "./registry";
import type {DocContent} from "./types";

type Guide={purpose:string;access:string;setup:string;steps:string[];features:string[];example:string;limits:string;errors:string[];related:string[];faq:[string,string]};
const guides:Record<string,Guide>={
 equipment:{purpose:"Le registre suit chaque véhicule ou matériel identifiable de l’entreprise, son responsable, son état et son historique d’intervention.",access:"Consulter le registre donne accès aux fiches et historiques. Gérer les biens permet les modifications, affectations, entretiens, incidents et archives ; ce droit inclut la lecture. La Direction reçoit les capacités du nouveau module sans réécriture de ses permissions stockées.",setup:"Activez Véhicules et équipements dans Modules. Préparez des codes uniques et accordez les droits utiles aux grades. Les entreprises existantes ne sont pas activées automatiquement.",steps:["Ajoutez un bien, son type, son code unique, son nom et ses informations RP.","Ouvrez sa fiche puis Affecter / retirer pour choisir un employé actif autorisé ou retirer l’affectation.","Ouvrez Entretien / incident, décrivez le travail et choisissez une échéance éventuelle.","Un incident bloquant rend le bien hors service ; un entretien le rend indisponible. La remise en service est refusée tant qu’un travail bloquant reste ouvert.","Clôturez avec une résolution. La remise en service est une option explicite et la prochaine révision peut être renseignée lors d’un entretien.","Consultez l’historique, filtrez les échéances atteintes, ou archivez après retour du bien et clôture de ses interventions."],features:["Véhicules et matériel, codes uniques, immatriculation, série, localisation, notes, dates et compteur non décroissant.","Responsable actif de la même entreprise, affectation/retrait et notification interne générique.","États Disponible, En entretien et Hors service avec blocages serveur.","Entretiens et incidents, échéances, clôtures motivées, résolution et historique paginé.","Recherche, types, états, biens confiés, échéances et archives ; CSV jusqu’à 5 000 biens et PDF jusqu’à 200."],example:"Une dépanneuse est confiée à Camille. Un incident de freinage la rend indisponible. La réparation est conservée dans l’historique ; la remise en service n’est autorisée que si aucun autre travail bloquant reste ouvert.",limits:"Un bien ne représente pas une quantité de produits. Aucun mouvement de stock, achat ou paiement n’est créé. Photos et pièces jointes privées, catégories personnalisées, carburant, correction exceptionnelle du compteur et rappels différés restent à développer. La clôture sans remise en service conserve l’état actuel du bien.",errors:["Fiche modifiée : rouvrez-la avant de réessayer.","Code ou plaque déjà utilisé : les archives gardent leur identité.","Responsable absent : vérifier emploi, compte et droits du registre.","Archivage refusé : retirer l’affectation et clôturer les interventions.","Remise en service refusée : clôturer les autres travaux bloquants."],related:["employes","stocks","documents","notifications"],faq:["Un départ d’employé efface-t-il l’affectation historique ?","Non. La fiche conserve le responsable désormais inactif jusqu’au retour ou à une nouvelle affectation. Cet ancien employé perd son accès selon son emploi actuel."]},
 statistics:{purpose:"Les statistiques regroupent les chiffres réellement enregistrés, selon les droits des modules sources. Elles ne donnent aucun accès supplémentaire aux données financières ou RH.",access:"Consulter les statistiques est nécessaire. Trésorerie : lecture Comptabilité. Ventes : lecture collective Ventes. Stock : lecture Stocks. Commandes : lecture Commandes. Services collectifs : lecture Employés, gestion Employés et utilisation Pointage, avec les modules concernés actifs.",setup:"Activez Statistiques avancées dans Modules et configurez les grades. Choisissez une période Paris de 1 à 366 jours. Les entreprises existantes conservent leurs modules désactivés jusqu’à une activation explicite.",steps:["Ouvrez Statistiques avancées et choisissez le début et la fin incluse de période avec les calendriers personnalisés.","Consultez les widgets autorisés puis choisissez un rapport : trésorerie, vendeurs, produits, services validés, stock ou commandes.","Personnalisez vos widgets : afficher/masquer et monter/descendre, puis enregistrez votre disposition personnelle.","Consultez les pages suivantes pour les classements complets.","Exportez le rapport choisi en CSV ou PDF. Réduisez la période ou affinez la sélection si le plafond est dépassé."],features:["Revenus et charges nets, contre-écritures, résultat de trésorerie RP, solde à la fin de période et comparaison avec la période précédente de même nombre de jours.","Évolution quotidienne Paris tenant compte des changements d’heure.","Ventes actives nettes par vendeur et produits vendus avant remise globale, avec prix historiques.","Services validés selon la révision actuelle du pointage : minutes, services et jours constatés.","Stock global/général actuel, seuils, alertes sans divulgation des coûts produit ; commandes créées sur la période par état actuel.","Widgets personnels persistés par emploi et entreprise ; CSV jusqu’à 5 000 lignes et PDF jusqu’à 200."],example:"La Direction compare ses flux RP sur trois jours. Une vente annulée produit une contre-écriture dans la trésorerie et n’est plus comptée parmi les ventes actives. Un transfert interne et un solde d’ouverture ne sont pas un revenu.",limits:"Le résultat est un résultat de trésorerie RP, pas un bénéfice fiscal. Les produits sont totalisés avant remise globale, pas selon une répartition fictive de la remise. Les services validés débutant dans la période sont comptés en totalité, sans prorata. Stocks, emplois et statuts de commande reflètent leur état actuel. Pas de reconstitution de stock historique, rapport programmé, prévision, marge historique ou consolidation interentreprises. Les widgets concernent la page Statistiques, pas encore l’accueil du Dashboard.",errors:["Source inaccessible : activer le module source et vérifier les permissions.","Disposition modifiée dans un autre onglet : rouvrir la personnalisation.","Période invalide : choisir de 1 à 366 jours.","Export trop volumineux : réduire la période ; aucune liste n’est silencieusement tronquée."],related:["tableau-de-bord","comptabilite","ventes","stocks","pointage"],faq:["Le droit Statistiques permet-il de lire les salaires individuels ?","Non. Les statistiques ne chargent ni salaire individuel ni note RH. Les sources gardent leurs propres permissions et contrôles d’activation."]},
 messages:{purpose:"La messagerie réunit des conversations privées à deux et des groupes limités à 25 participants de la même entreprise.",access:"Lire ses conversations est requis pour tout accès. Créer et envoyer demande aussi Envoyer des messages. La Direction dispose des nouvelles capacités sans réécriture des grades historiques, mais ne peut jamais lire un échange dont elle ne fait pas partie.",setup:"Activez Messagerie interne dans Modules, puis attribuez les permissions aux grades concernés. Les entreprises existantes ne sont pas activées automatiquement.",steps:["Ouvrez Messagerie interne puis Nouvelle conversation.","Choisissez Conversation privée ou Groupe et cherchez les collègues autorisés par leur nom RP.","Pour un groupe, indiquez un nom et choisissez jusqu’à 24 collègues en plus de vous.","Envoyez votre message. L’historique est conservé et paginé par 25 messages, les plus récents en page 1.","Recherchez dans les conversations ou dans la discussion ouverte, puis marquez les derniers messages comme lus.","Archivez pour vous. Un nouveau message replace l’échange dans la boîte de réception. Le créateur d’un groupe peut changer son nom et ses participants."],features:["Conversations privées réutilisées entre les mêmes deux personnes et groupes nommés.","Participants actifs de la même entreprise, compte et permissions vérifiés côté serveur.","Messages texte jusqu’à 4 000 caractères, commandes idempotentes et notifications génériques sans contenu privé.","Recherche, pagination serveur, non-lus exacts et position de lecture monotone.","Archives personnelles, historique conservé et retrait immédiat de l’accès d’un membre retiré."],example:"Deux mécaniciens échangent sur une intervention sans exposer leur discussion à toute la Direction. Un groupe Atelier partage son historique avec un collègue nouvellement ajouté.",limits:"Actualisation toutes les 20 secondes lorsque la page est visible, pas de temps réel WebSocket. Un nouveau participant de groupe peut consulter tout l’historique. Seul le créateur gère le groupe ; transfert de propriété et départ volontaire restent à développer. Sans créateur actif, les membres autorisés peuvent continuer à échanger mais ne peuvent pas gérer les participants. Pas de pièces jointes, modification ou suppression des messages, accusés de lecture individuels, blocage ou signalement d’abus dans ce lot. Limitation serveur de 60 actions par minute et par compte.",errors:["Conversation inaccessible : vérifier sa participation actuelle, son emploi, le module et les permissions.","Participant indisponible : son emploi, son compte ou ses droits ont changé.","Groupe modifié : actualiser avant d’enregistrer les participants.","Clé déjà utilisée : une même demande ne peut pas envoyer un texte différent."],related:["annonces","taches","notifications","confidentialite"],faq:["Archiver efface-t-il les messages pour les autres ?","Non. L’archive est personnelle, l’historique reste conservé et les autres participants gardent leur accès."]},
 cash:{purpose:"La caisse dédiée propose un catalogue rapide et un panier distincts visuellement de la page Ventes, en réutilisant exactement le même service de vente, de stock et de comptabilité.",access:"Enregistrer une vente est nécessaire. Consulter les ventes permet de voir l’historique collectif ; sans cette permission, un caissier ne consulte que ses propres tickets. Les remises demandent Appliquer une remise, et les remboursements Annuler une vente.",setup:"Activez Caisse dédiée dans Modules, avec Ventes, Produits et Comptabilité. Préparez les prix et le stock général. La Direction possède la nouvelle capacité de remise sans réécriture des anciennes permissions stockées.",steps:["Ouvrez Caisse dédiée dans Commerce et finances.","Recherchez par nom, référence ou catégorie et ajoutez les articles au panier.","Ajustez les quantités, le client RP, le mode de paiement et, si autorisé, la remise globale.","Vérifiez le total puis encaissez. Si les prix ont changé, utilisez Actualiser les prix puis confirmez le nouveau total.","Ouvrez le ticket enregistré et téléchargez son PDF.","Retrouvez la vente dans Historique des ventes. Un responsable autorisé peut enregistrer un remboursement intégral motivé."],features:["Catalogue serveur paginé par 24, recherche et catégories.","Panier jusqu’à 100 références, quantités et remise globale au centime.","Vente unique et atomique avec le formulaire habituel, vérification des prix et du stock général.","Tickets PDF privés, historique complet par 25, filtres et export CSV jusqu’à 5 000 ventes.","Remboursement intégral du net sur le compte RP d’origine, stock restitué une seule fois."],example:"Un atelier vend deux pneus avec une remise autorisée. Un seul ticket, une seule recette nette et les sorties de stock sont enregistrés. Un retour intégral inverse cette recette nette et restitue les pneus.",limits:"Remboursements partiels, promotions automatiques, avoirs, objectifs commerciaux et régularisation des commissions déjà versées restent à développer. La caisse utilise le stock général ; les autres entrepôts doivent être approvisionnés par transfert avant la vente. Aucun paiement bancaire réel.",errors:["Stock général insuffisant : corriger les quantités ou transférer les unités depuis la réserve.","Prix modifiés : actualiser les prix du panier et vérifier le total.","Remise refusée : la permission dédiée n’est pas accordée.","Clé déjà utilisée : une demande ne peut pas être réutilisée pour un autre panier."],related:["ventes","produits","stocks","comptabilite"],faq:["La caisse crée-t-elle une deuxième recette dans Ventes ?","Non. Les deux interfaces enregistrent et consultent la même vente ; aucun second encaissement n’est ajouté."]},
 documents:{purpose:"Un espace documentaire privé rassemble les fichiers de l’entreprise, classés dans des dossiers avec des versions conservées.",access:"Consulter les documents partagés permet la lecture des fichiers Équipe. Gérer les documents donne accès aux fichiers confidentiels et aux opérations de gestion. La Direction dispose de ces capacités dans le nouveau module ; les autres grades doivent les recevoir explicitement.",setup:"Activez Documents dans Modules puis configurez les grades. Les entreprises existantes ne sont pas activées automatiquement. Formats acceptés : PDF, PNG, JPEG et texte UTF-8 ; 5 Mo par fichier, 100 Mo par entreprise, anciennes versions et archives comprises.",steps:["Ouvrez Documents puis Dossiers pour créer un classement.","Ajoutez un document, son titre, son dossier, sa visibilité et une note de version.","Choisissez le fichier depuis le PC puis cliquez sur Transférer.","Ouvrez sa fiche pour prévisualiser ou télécharger une version précise.","Ajoutez une nouvelle version ou modifiez le titre, le dossier et les accès.","Archivez avec un motif. Pour restaurer un fichier classé dans un dossier archivé, restaurez d’abord le dossier."],features:["Dossiers plats, création, renommage, archivage et restauration.","Fichiers conservés en base et jamais exposés par une URL publique.","Recherche par titre, filtres dossier, accès, état et pagination serveur.","Versions immuables, auteur, note et historique paginé.","Prévisualisation des images et aperçu isolé du texte ; les PDF se téléchargent pour consultation.","Accès revérifié à chaque lecture et téléchargement, y compris les anciennes versions."],example:"Un atelier partage une procédure avec ses mécaniciens et réserve une version confidentielle aux responsables documentaires. Une ancienne procédure archivée reste téléchargeable aux personnes toujours autorisées.",limits:"100 dossiers, 50 versions par document. Les fichiers ne sont pas analysés par un antivirus. Aucun lien public, dossier imbriqué, suppression définitive ni rattachement aux fiches RH, tâches ou dépenses dans ce lot.",errors:["Accès refusé : vérifier le grade, l’emploi actif et l’activation du module.","Élément modifié : actualiser avant de réessayer.","Dossier non archivable : déplacer ou archiver ses documents actifs.","Document historique sans fichier : téléverser sa première version ; aucune donnée n’est inventée."],related:["catalogue-modules","permissions-entreprise","confidentialite"],faq:["Une nouvelle version remplace-t-elle définitivement l’ancien fichier ?","Non. Chaque version est conservée et reste soumise aux accès actuels du document."]},
 employees:{purpose:"Le dossier employé rassemble l’identité RP, le grade, le département et les événements de carrière d’une personne dans une entreprise. Il ne remplace pas son compte Discord : une même personne peut avoir plusieurs emplois avec des accès différents.",access:"La lecture dépend d’Employés. La gestion des invitations, affectations et notes RH demande Gérer les employés. Les notes privées restent réservées aux responsables autorisés ; la lecture de l’annuaire ne donne pas accès à tout le dossier RH.",setup:"Préparez les grades avant d’inviter. Le nom RP, le département et le salaire de référence appartiennent à l’emploi sélectionné. Les règles de paie peuvent ensuite préciser ce salaire.",steps:["Ouvrez Employés dans l’entreprise concernée, puis utilisez l’invitation d’un employé.","Saisissez l’e-mail du compte Discord destinataire et choisissez un grade autorisé, autre que Direction.","Copiez le lien d’invitation et transmettez-le vous-même au destinataire : aucun e-mail automatique n’est annoncé.","Après acceptation, ouvrez la fiche de la personne et vérifiez nom RP, département et grade.","Ajoutez les événements utiles : formation, certification ou carrière. Pour un départ, passez l’emploi en inactif plutôt que de supprimer son historique."],features:["Dossier RP, téléphone, fonction et biographie.","Notes RH, formations, certifications et historique de carrière.","Consultation des informations de planning, pointage, évaluations et sanctions selon les accès.","Modification du grade et du statut actif/inactif sans suppression des opérations antérieures."],example:"Un garage invite Camille comme mécanicien, renseigne son département Atelier, puis ajoute une certification moteur. Une note interne ne devient pas visible à tous les mécaniciens.",limits:"Photo privée, dépôt de documents et procédure détaillée de licenciement restent à développer.",errors:["Invitation refusée : vérifier le compte et l’e-mail Discord, l’expiration et le quota d’employés.","Grade absent : vous ne pouvez pas déléguer des permissions que vous ne possédez pas.","Réactivation refusée : vérifier les quotas de l’entreprise et du serveur affilié."],related:["invitations","grades","planning","pointage","paie","absences"],faq:["Un départ efface-t-il les ventes de l’employé ?","Non. L’inactivation de l’emploi conserve les opérations et l’historique déjà enregistrés."]},
 roles:{purpose:"Les grades décrivent les responsabilités dans une entreprise. Ils déterminent ce qu’un employé peut consulter ou modifier ; leur position dans la liste ne remplace jamais une permission.",access:"La page demande Gérer les grades et les accès. Seules les permissions déjà possédées peuvent être déléguées. Le grade Direction protégé ne se modifie pas comme un grade personnalisé.",setup:"Choisissez un nom compréhensible et le minimum de droits nécessaire. Distinguez consulter un module, y écrire et approuver les actions sensibles.",steps:["Ouvrez Grades et permissions et créez un grade personnalisé.","Nommez-le, puis sélectionnez les droits nécessaires à sa mission.","Enregistrez et consultez l’aperçu des accès effectifs.","Attribuez ce grade depuis Employés ou une invitation. L’activation des modules reste un réglage distinct.","Pour supprimer un grade utilisé, sélectionnez un grade de remplacement autorisé et indiquez le motif."],features:["Création et édition des grades personnalisés.","Duplication, modèles de permissions et ordre enregistré.","Aperçu des accès effectifs et réaffectation contrôlée avant suppression."],example:"Un restaurant donne aux serveurs le droit d’enregistrer une vente, mais réserve l’approbation des dépenses au responsable.",limits:"La hiérarchie fine et de nouvelles permissions spécialisées restent à développer. Un grade d’entreprise ne donne aucun droit d’administration communautaire.",errors:["Permission refusée : votre propre grade ne possède pas ce droit.","Suppression impossible : réaffecter employés et invitations ; votre propre grade ne peut pas être supprimé par cette action."],related:["employes","permissions-entreprise","catalogue-modules"],faq:["Désactiver un module retire-t-il les droits du grade ?","Non. L’activation du module et les droits sont vérifiés séparément ; les permissions sont conservées."]},
 planning:{purpose:"Le planning organise les services prévus. Un horaire prévu n’est pas une heure travaillée : le pointage reste la source des heures réellement constatées.",access:"Consulter le planning permet la lecture. Modifier les services est nécessaire pour créer, éditer ou annuler des services. Les indisponibilités sont distinguées des absences approuvées.",setup:"Sélectionnez jour, semaine ou mois et la période utile. Les séries suivent l’heure locale Europe/Paris, y compris lors d’un changement d’heure.",steps:["Ouvrez Planning, sélectionnez la période et les filtres de l’équipe.","Créez un service en choisissant employé, titre et horaires de début et de fin.","Vérifiez les conflits avec un autre service, une absence approuvée ou une indisponibilité.","Pour une répétition, renseignez la série et vérifiez les occurrences avant validation.","Pour corriger, ouvrez le service actuel. Annulez seulement l’occurrence ou la série selon votre besoin ; gardez son historique."],features:["Vues jour, semaine et mois avec filtres par période.","Disponibilités, récurrences et contrôles de conflits.","Modification avec révision, annulation individuelle ou de série et export CSV."],example:"Une équipe de transport programme un service chaque vendredi à 21 h, puis annule une seule occurrence pour une soirée communautaire.",limits:"Modèles de planning, échanges de services et notifications étendues ne sont pas encore livrés.",errors:["Chevauchement : modifier les horaires ou résoudre l’absence concernée.","Version obsolète : actualiser la page avant de modifier de nouveau.","Horaire invalide : la fin doit suivre le début."],related:["pointage","absences","employes","calendrier"],faq:["Un service planifié crée-t-il un pointage ?","Non. L’employé commence et termine son service dans Pointage."]},
 time:{purpose:"Le pointage mesure les services effectués dans Nyro Dashboard, avec les pauses déduites. Il fonctionne depuis le navigateur et ne détecte pas automatiquement une connexion au serveur de jeu.",access:"Pointer ses services permet les actions personnelles. Les responsables RH autorisés peuvent corriger, clôturer, valider, refuser ou rouvrir les pointages. La consultation des autres employés reste contrôlée.",setup:"Utilisez les filtres de période et de statut. Un service ouvert est provisoire. Pour la paie horaire, seuls les pointages clôturés et approuvés de la période sont retenus.",steps:["Ouvrez Pointage et commencez votre service une seule fois.","Démarrez une pause quand nécessaire, puis reprenez le service à votre retour.","Terminez le service ; contrôlez la durée nette affichée.","Un responsable vérifie les horaires, apporte une correction motivée si nécessaire et valide ou refuse.","Consultez les totaux validés ou exportez la sélection en CSV/PDF avec les accès requis."],features:["Début, fin, pauses et protection contre les doubles commandes.","Correction conservant les horaires d’origine et décisions de validation.","Filtres, pagination, totaux nets et validés, exports et liaison avec la paie."],example:"Un mécanicien effectue 120 minutes avec une pause de 15 minutes : 105 minutes nettes peuvent être validées pour la paie.",limits:"Les demandes de correction initiées par l’employé et les règles avancées d’heures supplémentaires hors paie restent à développer.",errors:["Service déjà ouvert : terminer celui-ci avant d’en commencer un autre.","Heures absentes du bulletin : vérifier clôture, approbation et période.","Modification concurrente : actualiser avant de reprendre la correction."],related:["planning","paie","employes"],faq:["Fermer le navigateur termine-t-il mon service ?","Non. Terminez explicitement le service ; un responsable peut clôturer un oubli avec un motif."]},
 leaves:{purpose:"Les absences enregistrent les indisponibilités demandées par un employé et la décision de ses responsables. La motivation est privée ; ce module ne gère pas encore un solde légal de congés.",access:"Consulter ses absences permet de voir ses demandes. Valider les absences autorise les décisions sur les demandes des autres ; l’auto-validation est refusée.",setup:"Un responsable peut préparer des types d’absence. L’archivage d’un type conserve son libellé dans les demandes historiques. Utilisez une période et un motif RP précis.",steps:["Ouvrez Absences et créez une demande avec début, fin, type et motif.","Vérifiez les dates puis envoyez la demande ; elle reste en attente jusqu’à décision.","Un autre responsable autorisé consulte le dossier et vérifie les services en conflit.","Il accepte ou refuse avec un motif ; l’annulation de services en conflit doit être explicite.","Retrouvez la décision dans votre liste ou calendrier. Utilisez l’annulation prévue si votre situation change."],features:["Demandes personnelles privées et décisions motivées.","Types personnalisés, archivage, listes et calendrier paginés.","Annulation conservatrice et gestion explicite des conflits de planning."],example:"Une serveuse demande son absence pour la soirée de samedi. Le responsable libère explicitement le service concerné en acceptant.",limits:"Justificatifs privés, soldes de congés et politiques avancées ne sont pas disponibles.",errors:["Auto-validation interdite : demander à un autre responsable.","Conflit planning : choisir explicitement son traitement.","Type archivé : sélectionner un type encore actif pour une nouvelle demande."],related:["planning","employes","permissions-entreprise"],faq:["Une demande en attente annule-t-elle mes services ?","Non. La décision et le traitement des conflits doivent être effectués par un responsable autorisé."]},
 recruitment:{purpose:"Le recrutement relie les offres publiques RP aux candidatures déposées avec Discord. Une proposition d’embauche n’ajoute un employé qu’après acceptation du candidat.",access:"Les responsables disposant de Gérer les employés pilotent le recrutement de l’entreprise. Les candidats voient leurs propres candidatures dans Mes candidatures ; les notes RH restent privées.",setup:"Activez Recrutement et Employés. Préparez un grade autorisé, la présentation du poste et les conditions RP. Vérifiez la capacité d’accueil avant la proposition.",steps:["Ouvrez Recrutement et préparez une offre en brouillon.","Publiez-la pour la rendre visible dans l’annuaire de recrutement.","Le candidat se connecte avec Discord, ouvre l’offre et transmet sa candidature.","Traitez les étapes, l’entretien et les notes internes, puis envoyez une proposition de grade.","Le candidat accepte depuis Mes candidatures. Vérifiez ensuite son arrivée dans Employés ; un refus ou retrait conserve l’historique."],features:["Offres brouillon, publiées ou fermées et annuaire public paginé.","Candidatures personnelles, entretiens, notes RH, refus et propositions.","Acceptation explicite, création de l’emploi, quotas et historique."],example:"Un restaurant publie un poste de cuisinier ; l’entretien est enregistré, puis le candidat accepte la proposition avant de rejoindre l’équipe.",limits:"Formulaires personnalisés, pièces jointes et relances programmées restent à développer. L’historique détaillé est actuellement borné aux 100 événements affichés.",errors:["Offre inaccessible : vérifier publication et statut de l’entreprise.","Embauche refusée : contrôler quota, grade et acceptation du candidat.","Déjà employé : ne pas créer un doublon d’emploi."],related:["employes","invitations","grades","quotas"],faq:["Publier une offre donne-t-il accès aux notes RH ?","Non. Les notes internes et les candidatures des autres personnes ne sont pas publiques."]},
 payroll:{purpose:"La paie calcule des bulletins internes RP à partir des règles applicables, des heures approuvées et, si configuré, des ventes. Aucun virement bancaire réel ni versement automatique en jeu n’est effectué.",access:"Les responsables RH gèrent les règles et brouillons. Un versement exige aussi Administrer l’entreprise, Consulter la comptabilité et Valider les dépenses, avec Finance actif. Un autre responsable doit valider son propre bulletin.",setup:"Choisissez une règle individuelle ou par grade, un mode forfaitaire ou horaire, les taux et commissions. La règle individuelle est prioritaire. Une règle horaire demande Pointage ; les commissions demandent Ventes.",steps:["Ouvrez Salaires et primes et préparez les règles de calcul.","Créez une période non chevauchante contenant les services à payer.","Préparez les bulletins à partir des sources validées ; renseignez les primes ou retenues avec leur motif.","Relisez le calcul et faites valider le bulletin par une personne autorisée distincte quand nécessaire.","Effectuez le versement RP. Consultez l’écriture comptable et téléchargez le PDF privé du bulletin."],features:["Forfait, taux horaire, seuil de majoration et commissions configurées.","Primes et retenues motivées, révisions et contrôle des sources périmées.","Validation, versement comptabilisé une seule fois et historique paginé."],example:"Une société de transport rémunère 105 minutes approuvées à son taux horaire et ajoute une prime RP motivée. Le paiement produit une dépense interne.",limits:"Les régularisations après versement et après de futurs remboursements partiels ne sont pas implémentées. Un bulletin versé n’est pas librement réécrit.",errors:["Heures manquantes : vérifier approbation, période et fin du service.","Sources modifiées : recalculer et faire valider la nouvelle version.","Versement interdit : contrôler les trois permissions financières et le module Finance."],related:["pointage","ventes","comptabilite","grades"],faq:["Le salaire du dossier employé suffit-il ?","Il sert de référence en l’absence de règle spécifique. Vérifiez toujours le détail du calcul avant validation."]},
 reviews:{purpose:"Les évaluations structurent un entretien RP autour de critères pondérés et d’objectifs. Le résultat n’est visible personnellement qu’après publication ; une note RH interne reste privée.",access:"La gestion nécessite les droits RH. Un employé ne peut consulter que ses propres dossiers publiés avec son accès autorisé ; il ne voit pas les brouillons d’un autre employé.",setup:"Préparez un modèle et ses critères pondérés, puis une campagne ou un entretien. Les critères utilisés sont figés dans le dossier pour préserver son contexte historique.",steps:["Ouvrez Évaluations et préparez le modèle de critères.","Créez la campagne ou le dossier de l’employé concerné.","Renseignez les appréciations, l’entretien et les objectifs mesurables.","Relisez les champs publics et les notes RH privées avant de publier.","L’employé consulte le dossier publié et accuse réception ; suivez ensuite la progression des objectifs."],features:["Critères pondérés, campagnes, entretiens et objectifs.","Notes internes séparées, publication et accusé de lecture.","Progression et historique paginé depuis le module ou le dossier employé."],example:"Un garage suit ponctualité, qualité des réparations et accueil client, puis fixe un objectif de certification pour le prochain entretien.",limits:"Permissions plus fines, restitution détaillée de toutes les versions et restauration de brouillons archivés restent à développer.",errors:["Dossier invisible : vérifier publication et destinataire.","Enregistrement obsolète : actualiser avant de reprendre.","Critère incomplet : compléter les valeurs requises avant publication."],related:["employes","sanctions","permissions-entreprise"],faq:["L’accusé de lecture signifie-t-il accord avec l’évaluation ?","Il atteste la lecture dans Nyro Dashboard ; il ne constitue pas une signature juridique."]},
 sanctions:{purpose:"Les sanctions internes décrivent des faits et une décision dans le cadre du Roleplay. Elles conservent une trace motivée et confidentielle sans provoquer automatiquement de changement de grade ou de salaire.",access:"La gestion est réservée aux responsables RH autorisés. L’employé concerné accède uniquement à son dossier publié ; les notes internes ne deviennent pas publiques.",setup:"Préparez des types de décision RP et distinguez faits, décision et notes internes. N’enregistrez pas de données réelles sensibles inutiles au Roleplay.",steps:["Ouvrez Sanctions internes et créez un brouillon pour le bon employé.","Sélectionnez le type puis décrivez les faits et la décision avec un motif clair.","Relisez le destinataire et les champs privés, puis publiez.","L’employé consulte sa décision et accuse réception.","Si la décision doit être retirée, utilisez la révocation motivée ; l’historique est conservé."],features:["Types de sanction RP et brouillons confidentiels.","Publication personnelle et accusé de lecture.","Révocation, archivage conservateur et historique dans le dossier RH."],example:"Un transporteur consigne un avertissement RP pour absence non justifiée, puis le révoque après examen d’une erreur de planning.",limits:"Pièces jointes privées et permissions plus fines ne sont pas livrées. Aucune retenue de paie ou rétrogradation automatique.",errors:["Dossier non visible : vérifier s’il est encore brouillon.","Modification concurrente : actualiser la révision.","Action refusée : vérifier les droits RH et l’activation du module."],related:["employes","evaluations","paie"],faq:["Une sanction diminue-t-elle automatiquement la paie ?","Non. Une décision RP et les opérations de paie sont des actions distinctes, soumises à leurs propres droits."]},
 sales:{purpose:"Ventes et caisse enregistre les transactions RP de l’entreprise à partir du catalogue. Une vente validée diminue les références suivies en stock et alimente le journal financier interne dans une même opération.",access:"Consulter les ventes donne la lecture. Enregistrer une vente permet de valider une caisse ; Annuler une vente est un droit distinct. Produits et Comptabilité doivent être actifs.",setup:"Créez les produits et prestations, leurs prix et le suivi éventuel du stock. Ajoutez les quantités disponibles avant d’encaisser des articles physiques.",steps:["Ouvrez Ventes et caisse et commencez une nouvelle vente.","Choisissez les produits et leurs quantités dans le catalogue.","Renseignez le client RP et le mode de règlement déclaré.","Contrôlez le total avant validation ; les prix et la capacité du stock sont vérifiés côté serveur.","Consultez la vente dans l’historique. Pour une erreur, utilisez l’annulation motivée avec le droit approprié."],features:["Panier de produits, quantités, client et mode de paiement RP.","Prix historiques, baisse du stock et recette comptable atomiques.","Protection contre les doubles validations et annulation compensatrice tracée.","Historique complet paginé, filtres serveur, tickets PDF et export CSV de la sélection."],example:"Un garage facture une réparation et deux pièces. Les pièces suivies sortent du stock ; la recette apparaît en Comptabilité sans connexion à FiveM.",limits:"La caisse dédiée dispose de remises globales autorisées et de tickets PDF. Promotions automatiques, remboursements partiels et avoirs restent à développer. Les devis et factures possèdent un parcours distinct : ne comptabilisez pas deux fois le même paiement.",errors:["Stock insuffisant : corriger la quantité ou enregistrer l’entrée réelle.","Produit archivé : choisir une référence active.","Accès refusé : vérifier Produits, Finance et les droits de création."],related:["produits","stocks","comptabilite","factures"],faq:["Une vente retire-t-elle l’argent du joueur en jeu ?","Non. Le mode de paiement décrit une opération RP saisie sur le site ; aucune banque en jeu n’est actionnée."]},
 products:{purpose:"Le catalogue centralise les références vendues, leurs prix RP, coûts et seuils. Une prestation peut rester sans suivi de stock ; un article physique peut être suivi en quantité.",access:"Voir le catalogue permet la lecture. Gérer le catalogue est nécessaire pour créer, modifier ou archiver. Les ajustements de quantité utilisent les droits Stocks.",setup:"Préparez une référence SKU unique, une catégorie, un prix de vente et un coût. Le seuil indique quand la quantité devient faible ; il ne commande rien automatiquement.",steps:["Ouvrez Produits et prestations puis créez une référence.","Renseignez nom, SKU, catégorie, prix et coût.","Choisissez si la référence est suivie en stock et renseignez son état initial dans le parcours disponible.","Enregistrez puis vérifiez la référence dans la caisse et les stocks.","Archivez une référence qui n’est plus utilisée ; les opérations passées gardent leur contexte."],features:["Catalogue de produits et de prestations.","Prix, coûts, marges indicatives et catégories.","Seuils de stock et archivage des références."],example:"Un restaurant distingue la prestation Livraison, non stockée, et une boisson suivie en quantité avec un seuil d’alerte.",limits:"Images, descriptions enrichies, variantes et import/export du catalogue restent à développer.",errors:["Référence existante : utiliser un SKU distinct.","Montant invalide : saisir une valeur positive dans le format de l’interface.","Quantité à modifier : utiliser Stocks afin de conserver un mouvement motivé."],related:["ventes","stocks","commandes-fournisseurs"],faq:["Modifier un prix réécrit-il une vente passée ?","Non. Les opérations enregistrées conservent leurs montants historiques."]},
 inventory:{purpose:"Stocks suit les quantités internes RP et chaque mouvement qui les explique. Vous pouvez gérer l’état initial, des réceptions, consommations, pertes et inventaires directement sur le site, sans script de jeu.",access:"Consulter les stocks permet la lecture. Ajuster les stocks permet les mouvements et comptages. Produits doit être actif ; les réceptions fournisseur passent par Commandes d’achat.",setup:"Vérifiez que le produit est suivi en stock, son coût et son seuil. Créez les entrepôts nécessaires. Une quantité non affectée est distincte des quantités affectées à un entrepôt.",steps:["Ouvrez Stocks et sélectionnez le produit ou filtrez ses mouvements.","Pour une entrée ou sortie manuelle, choisissez le type, la quantité, la date et un motif.","Pour un transfert, choisissez source et destination distinctes, puis la quantité disponible.","Pour un inventaire, préparez le comptage, saisissez les quantités constatées et expliquez les écarts.","Actualisez un comptage devenu obsolète avant validation. Vérifiez les mouvements produits et exportez la sélection en CSV/PDF."],features:["Mouvements datés, compensation motivée et refus des stocks négatifs.","Entrepôts, allocations et transferts atomiques entre emplacements.","Inventaires révisés, écarts, recherche, pagination et valorisation au coût catalogue.","Réceptions fournisseur partielles ou complètes liées au journal financier."],example:"Un garage réceptionne 8 pneus sur 12 commandés, affecte 4 pneus à son entrepôt, puis constate une perte motivée. Le reliquat fournisseur reste visible.",limits:"Sous-emplacements, inventaires physiques par entrepôt, imports avec aperçu et retours fournisseurs partiels restent à développer. Un entrepôt n’est pas une succursale.",errors:["Stock insuffisant : vérifier aussi la disponibilité de l’emplacement source.","Comptage obsolète : actualiser les références avant de publier les écarts.","Produit non suivi : choisir un article physique autorisé."],related:["produits","ventes","fournisseurs","commandes-fournisseurs","comptabilite"],faq:["Un inventaire synchronise-t-il mon coffre FiveM ?","Non. Il enregistre les quantités constatées dans Nyro Dashboard ; le coffre du jeu reste indépendant."]},
 finance:{purpose:"La comptabilité est un journal financier interne RP. Elle calcule les soldes à partir d’écritures traçables ; elle ne consulte ni ne modifie les comptes bancaires réels ou ceux du jeu.",access:"Consulter la comptabilité permet la lecture. Les opérations et réglages demandent aussi Administrer l’entreprise ; les décisions de validation demandent Valider les dépenses. Ces droits sont contrôlés côté serveur.",setup:"Créez vos comptes RP (caisse, banque, autre), choisissez le compte par défaut et préparez des catégories. Pour démarrer, enregistrez un solde d’ouverture comme opération datée plutôt que de remplacer le solde affiché.",steps:["Ouvrez Comptabilité, préparez les comptes et catégories nécessaires.","Créez une recette, une dépense, une ouverture ou un transfert avec montant, date et libellé.","Contrôlez le brouillon ; modifiez-le avant publication si nécessaire.","Publiez ou soumettez l’opération selon les validations requises, puis consultez les écritures générées.","Pour corriger une opération publiée, utilisez une contre-écriture motivée. Pour vérifier un compte, comparez son solde calculé à un montant observé avec un rapprochement."],features:["Comptes, catégories, ouvertures et brouillons révisables.","Recettes, dépenses, transferts et validations.","Contre-écritures conservant l’original, journal filtré et rapprochements.","Comparaisons de périodes et exports CSV/PDF calculés côté serveur."],example:"Une entreprise ouvre une caisse à 1 000 $ RP, enregistre 300 $ de recettes et 80 $ de dépenses : son journal explique 1 220 $. Un rapprochement constate l’écart sans masquer l’historique.",limits:"Justificatifs privés, clôtures avancées, notes de frais et rapprochement automatique entre vente et facture restent à développer.",errors:["Compte archivable seulement à zéro et sans opération en attente.","Transfert refusé : choisir deux comptes actifs distincts et une somme valide.","Approbation impossible : vérifier le droit financier requis et le statut actuel."],related:["ventes","depenses","factures","paie","stocks"],faq:["Puis-je saisir les finances sans être connecté à FiveM ?","Oui. Tous les comptes et opérations RP sont gérés dans Nyro Dashboard de manière autonome."]},
 expenses:{purpose:"Dépenses suit les sorties RP courantes et leur approbation. Une dépense n’est pas forcément comptabilisée dès sa saisie : son statut et le seuil de l’entreprise déterminent son traitement.",access:"Consulter les dépenses, Créer une dépense et Valider les dépenses sont des droits distincts. Finance doit être actif.",setup:"Un responsable configure le seuil de validation dans Paramètres. Préparez un libellé précis et une catégorie cohérente avant de saisir le montant.",steps:["Ouvrez Dépenses et commencez une nouvelle dépense.","Saisissez le libellé, la catégorie et le montant RP.","Enregistrez et consultez le statut obtenu selon le seuil applicable.","Un responsable autorisé accepte ou refuse une demande en attente.","Vérifiez le résultat dans la liste puis en Comptabilité ; ne recréez pas une deuxième dépense pour le même règlement."],features:["Saisie d’une dépense et classement par catégorie.","Seuil de validation et décision autorisée.","Écriture comptable unique lors du traitement approprié."],example:"Un restaurant soumet un achat de fournitures de 900 $ RP au responsable lorsque le seuil de validation est dépassé.",limits:"Justificatifs, notes de frais, plafonds individuels et remboursements avancés restent à développer.",errors:["Dépense en attente : demander une validation plutôt que la saisir à nouveau.","Montant nul ou négatif : corriger le formulaire.","Validation refusée : contrôler le grade et le statut de la dépense."],related:["comptabilite","configurer-entreprise","commandes-fournisseurs"],faq:["Une dépense refusée débite-t-elle automatiquement le journal ?","Non. Consultez son statut et le journal ; une décision ne doit pas être remplacée par un doublon manuel."]},
 crm:{purpose:"Le CRM conserve les coordonnées Roleplay et les informations commerciales des clients de votre entreprise. Les devis et factures peuvent être retrouvés à partir de la relation client.",access:"Consulter les clients permet la lecture du CRM autorisé. Gérer les clients permet la création, l’édition et l’archivage. N’ajoutez pas de données réelles sensibles dans les notes RP.",setup:"Choisissez un segment, par exemple Particulier ou Professionnel, et les coordonnées réellement utiles au Roleplay. Les informations restent propres à l’entreprise.",steps:["Ouvrez Clients et CRM et ajoutez un client.","Renseignez nom, téléphone et e-mail RP si pertinents.","Choisissez le segment et ajoutez une note commerciale utile.","Enregistrez, puis retrouvez ses documents depuis les modules Devis ou Factures.","Archivez une relation qui n’est plus utilisée au lieu de recréer des fiches identiques."],features:["Fiches clients, coordonnées, segments et notes.","Édition et archivage.","Liens avec les documents commerciaux RP."],example:"Une concession distingue les clients particuliers et les flottes professionnelles, puis prépare un devis pour une société de transport.",limits:"Rendez-vous CRM, relances, achats liés et recherche serveur avancée ne sont pas livrés.",errors:["Client absent du document : sélectionner un client autorisé et actif.","Données d’une autre entreprise : changer d’espace ; elles ne sont pas partagées automatiquement."],related:["devis","factures","confidentialite"],faq:["Les clients reçoivent-ils un e-mail automatique ?","Non. Aucun envoi commercial automatique n’est configuré dans cette version."]},
 quotes:{purpose:"Un devis prépare une proposition commerciale RP avant facturation. Ses lignes, quantités et remises définissent le montant proposé ; accepter un devis ne constitue pas un encaissement.",access:"Consulter les devis permet la lecture. Gérer les devis permet de créer, émettre et enregistrer la décision. Le CRM doit être actif ; la conversion demande aussi Factures et les droits associés.",setup:"Créez le client, préparez les lignes et une éventuelle date de validité. Les remises du devis sont distinctes des futures promotions de caisse.",steps:["Ouvrez Devis et préparez un brouillon pour le client.","Ajoutez les libellés, quantités, prix unitaires et remise éventuelle.","Relisez les notes et la validité, puis émettez le document.","Enregistrez l’acceptation ou le refus RP selon la décision du client.","Si Factures est actif, convertissez une seule fois le devis accepté et suivez le règlement dans la facture."],features:["Brouillons, lignes, notes et remises.","Émission, validité et décision RP.","Conversion contrôlée en facture sans double conversion."],example:"Un garage propose la remise en état d’une flotte, attend l’accord RP, puis crée la facture à partir du devis accepté.",limits:"Modèles personnalisés, PDF serveur et envoi sécurisé restent à développer. Le devis ne réalise pas de signature juridique.",errors:["Modification refusée : seules les transitions compatibles avec le statut sont permises.","Conversion impossible : vérifier acceptation, activation Factures et permissions.","Déjà converti : retrouver la facture existante."],related:["clients-crm","factures","comptabilite"],faq:["Accepter un devis ajoute-t-il de l’argent au solde ?","Non. L’encaissement est enregistré séparément dans le parcours de la facture."]},
 invoices:{purpose:"Les factures décrivent une créance et son règlement interne RP. Elles ne sont pas des factures fiscales réelles et ne déclenchent aucun prélèvement ni paiement bancaire.",access:"Consulter les factures donne la lecture. Gérer les factures permet les opérations autorisées sur leurs statuts et règlements ; CRM et Comptabilité doivent être actifs.",setup:"Préparez la fiche client et les lignes de la facture, ou convertissez un devis accepté. Évitez d’enregistrer le même encaissement à la fois comme vente et règlement de facture.",steps:["Ouvrez Factures et créez un brouillon, ou ouvrez la facture issue d’un devis.","Vérifiez le client, les lignes, les prix et la remise.","Émettez le document pour figer sa proposition de règlement RP.","Quand le règlement RP est constaté, enregistrez-le via le changement de statut prévu et vérifiez l’écriture comptable.","Pour une erreur, utilisez l’annulation autorisée avec motif. Ouvrez le document imprimable depuis son lien privé."],features:["Brouillon, émission et règlement RP.","Écriture comptable liée et contre-écriture d’annulation.","Vue imprimable privée, accessible uniquement avec les autorisations nécessaires."],example:"Un transporteur émet une facture RP à son client puis enregistre le règlement reçu dans le cadre du jeu, sans action automatique sur sa banque FiveM.",limits:"PDF serveur dédié, envoi automatique, modèles et historique enrichi restent à développer. L’impression dépend du navigateur.",errors:["Statut incompatible : vérifier l’état actuel avant de recommencer.","Impression refusée : se connecter avec un compte autorisé dans la bonne entreprise.","Solde doublé : distinguer vente de caisse et règlement de facture."],related:["devis","clients-crm","comptabilite","paiements"],faq:["Le bouton de règlement débite-t-il un vrai compte ?","Non. Il constate un règlement RP et produit les écritures internes prévues."]},
 suppliers:{purpose:"Le répertoire fournisseurs prépare les achats RP. Il conserve les contacts, notes et références nécessaires aux commandes de l’entreprise.",access:"Consulter les fournisseurs permet la lecture. Gérer les fournisseurs autorise création, modification et archivage. Une commande exige ses propres droits.",setup:"Préparez des coordonnées RP cohérentes et un nom identifiable. Évitez les notes confidentielles étrangères au contexte de l’entreprise.",steps:["Ouvrez Fournisseurs et ajoutez une fiche.","Renseignez les informations de contact et les notes utiles.","Enregistrez et vérifiez que la fiche est active.","Sélectionnez ce fournisseur lors de la préparation d’une commande d’achat.","Archivez-le lorsqu’il ne doit plus être proposé pour de nouveaux achats."],features:["Répertoire, contacts et notes.","Édition et archivage conservateur.","Sélection dans les bons de commande RP."],example:"Un restaurant crée son grossiste alimentaire comme fournisseur, puis prépare une commande des références déjà présentes au catalogue.",limits:"Historique commercial enrichi, suivi transporteur et échanges automatiques ne sont pas disponibles.",errors:["Fournisseur non proposé : vérifier l’archivage et l’entreprise active.","Commande impossible : vérifier les droits et les modules Stocks, Produits et Finance."],related:["commandes-fournisseurs","stocks","produits"],faq:["Créer un fournisseur lui envoie-t-il une commande ?","Non. Le répertoire et les bons d’achat restent des enregistrements RP internes."]},
 orders:{purpose:"Les commandes d’achat suivent les quantités commandées et réellement reçues. Chaque réception validée met à jour le stock et le coût livré dans les finances, sans attendre une livraison complète.",access:"Consulter les commandes donne la lecture. Gérer les commandes et réceptions autorise le traitement ; Fournisseurs, Stocks et Finance doivent être actifs et accessibles selon l’opération.",setup:"Préparez un fournisseur actif et des produits physiques suivis en stock. Les coûts unitaires saisis dans le bon décrivent cet achat et ne doivent pas être confondus avec un encaissement client.",steps:["Ouvrez Commandes d’achat et préparez un bon en brouillon.","Choisissez le fournisseur et ajoutez chaque référence une seule fois avec quantité et coût.","Validez le statut requis pour permettre la réception.","À la livraison, saisissez uniquement les quantités réellement reçues et la date. Une réception partielle conserve le reliquat.","Consultez reçus/restants, l’historique, les mouvements de stock et les dépenses produites. Annulez le reliquat si nécessaire sans effacer les réceptions passées."],features:["Bons, lignes et statuts de commande.","Livraisons datées partielles ou complètes avec historique paginé.","Stock et coût livré enregistrés ensemble, sans double réception.","Annulation du reliquat conservant les quantités déjà livrées."],example:"Un garage commande 12 pneus, en reçoit 8 aujourd’hui puis 4 demain. Seules les quantités livrées entrent dans les stocks à chaque réception.",limits:"La liste affiche les 500 commandes les plus récentes. Retours fournisseurs, pièces jointes, PDF et suivi transporteur restent à développer.",errors:["Réception excessive : ne pas dépasser le restant à livrer.","Produit refusé : choisir une référence active et suivie en stock.","Commande annulée : les réceptions ne peuvent pas contourner son statut."],related:["fournisseurs","produits","stocks","comptabilite"],faq:["Annuler le reliquat retire-t-il les produits déjà reçus ?","Non. Les réceptions passées restent enregistrées ; un retour fournisseur automatique n’est pas disponible."]},
 tasks:{purpose:"Les tâches organisent le travail d’équipe avec des responsables, échéances et étapes. Leur historique explique les évolutions sans transformer les commentaires en messagerie privée.",access:"Voir les tâches donne la lecture autorisée. Gérer les tâches permet l’administration. Les employés assignés peuvent commenter, suivre leur état et cocher leur checklist avec leur accès de lecture existant.",setup:"Choisissez les colonnes de travail et les statuts personnalisés utiles. Préparez des descriptions et échéances lisibles plutôt que de multiplier les tâches identiques.",steps:["Ouvrez Tâches et créez une action avec titre et description.","Assignez un employé, choisissez une priorité, une échéance et un statut.","Ajoutez les étapes de checklist nécessaires.","L’employé assigné met à jour le suivi et les commentaires autorisés.","Consultez les vues liste/Kanban puis archivez une tâche terminée ; restaurez-la si nécessaire."],features:["Statuts, liste et Kanban avec lecture paginée.","Assignations, priorités, échéances et checklists.","Commentaires, notifications internes, historique et archivage/restauration."],example:"Un garage organise une préparation de véhicule avec trois étapes : diagnostic, réparation et contrôle final.",limits:"Glisser-déposer, pièces jointes privées et relances programmées d’échéance restent à développer.",errors:["Action interdite : vérifier si vous êtes assigné ou gestionnaire.","Employé absent : choisir un membre actif de l’entreprise.","Révision obsolète : actualiser avant une nouvelle modification."],related:["employes","annonces","calendrier"],faq:["Une échéance envoie-t-elle automatiquement une relance ?","Non. Les notifications internes des actions existent ; les rappels différés ne sont pas implémentés."]},
 announcements:{purpose:"Les annonces diffusent une information générale ou départementale. La programmation contrôle la visibilité dans Nyro Dashboard ; elle ne constitue pas un envoi Discord ou e-mail.",access:"L’accès de lecture au tableau de bord et l’activation du module sont nécessaires. La gestion demande aussi Administrer l’entreprise. Les brouillons restent réservés aux responsables ; les annonces départementales suivent l’affectation actuelle.",setup:"Choisissez la portée, la priorité, les dates de visibilité et l’éventuelle confirmation de lecture. Vérifiez le département avant la publication.",steps:["Ouvrez Annonces internes et préparez un brouillon.","Renseignez le titre et le contenu, puis les destinataires généraux ou départementaux.","Choisissez la publication immédiate ou les dates de visibilité et d’expiration.","Publiez et épinglez si nécessaire avec vos droits.","Suivez les lectures autorisées ; archivez ou restaurez une annonce sans supprimer l’historique."],features:["Brouillons, portée générale ou départementale, priorités et épinglage.","Visibilité programmée, expiration et archivage/restauration.","Confirmations de lecture, historique paginé et notifications internes immédiates ciblées."],example:"Un restaurant publie les consignes d’un événement uniquement à l’équipe Cuisine, avec confirmation de lecture.",limits:"L’envoi différé d’une notification au moment d’une publication programmée reste à développer. La visibilité datée fonctionne indépendamment de cet envoi.",errors:["Annonce invisible : vérifier portée, département, dates et statut.","Modification refusée : vérifier les droits de gestion et la révision.","Notification absente : une programmation ne crée pas encore de rappel différé."],related:["employes","notifications","calendrier"],faq:["L’annonce est-elle envoyée dans mon serveur Discord ?","Non. Les notifications livrées par ce module sont internes à Nyro Dashboard."]},
 calendar:{purpose:"Le calendrier organise les réunions et événements RP. Il distingue une publication partagée d’un événement privé réservé à ses invités et à la direction autorisée.",access:"La lecture exige l’accès au tableau de bord et Calendrier actif. La gestion demande aussi Administrer l’entreprise. Les réponses et observations personnelles sont limitées aux personnes autorisées.",setup:"Préparez le type réunion/événement, les dates, la visibilité et les invités actifs. Les récurrences conservent les horaires Europe/Paris.",steps:["Ouvrez Calendrier et choisissez mois, semaine ou agenda.","Créez un événement avec titre, dates, type et visibilité.","Choisissez les invités et une éventuelle récurrence.","Les invités répondent personnellement depuis le calendrier ; la direction suit la participation autorisée.","Annulez une occurrence ou une série avec un motif si nécessaire. Consultez son historique conservé."],features:["Événements partagés ou privés et invitations.","Réponses personnelles, récurrences et participation constatée.","Annulation individuelle/de série, historique et notifications internes immédiates."],example:"Une société de transport invite ses chefs d’équipe à une réunion privée hebdomadaire ; les autres employés ne voient pas le dossier privé.",limits:"Rappels différés durables, échanges avec des calendriers externes et alertes avancées de conflit restent à développer.",errors:["Événement absent : vérifier période, visibilité et invitation.","Réponse refusée : seule une personne invitée active répond pour elle-même.","Période excessive : réduire la sélection du calendrier."],related:["planning","annonces","notifications"],faq:["Un événement crée-t-il un service au planning ?","Non. Calendrier et Planning sont deux modules distincts ; une réunion ne produit pas d’heures de pointage."]},
 dashboard:{purpose:"Le tableau de bord donne une vue synthétique de l’entreprise sélectionnée. Ses indicateurs proviennent des données autorisées, pas d’une synchronisation implicite avec le serveur de jeu.",access:"Voir le tableau de bord est requis. Les chiffres sensibles restent limités par les accès aux domaines concernés ; un simple emploi ne donne pas accès à toutes les finances.",setup:"Sélectionnez d’abord la bonne entreprise et activez les modules nécessaires. Un espace vide ou un module désactivé peut expliquer l’absence d’indicateurs.",steps:["Ouvrez votre entreprise depuis la sélection des espaces.","Vérifiez son nom dans le sélecteur avant d’interpréter les chiffres.","Consultez les indicateurs disponibles et les graphiques affichés.","Ouvrez le module d’origine pour retrouver le détail des écritures ou opérations.","Actualisez après une nouvelle opération et comparez les mêmes périodes."],features:["Indicateurs réels et activité de l’entreprise.","Graphiques selon les projections disponibles.","Navigation vers les outils autorisés et changement d’entreprise."],example:"Une direction retrouve l’activité commerciale puis consulte le journal financier pour expliquer le solde RP affiché.",limits:"Widgets persistés, bénéfice avancé et synthèses étendues des demandes et événements restent à développer.",errors:["Chiffres inattendus : vérifier entreprise, période et annulations.","Indicateur absent : contrôler accès et activation du module source."],related:["navigation-dashboard","comptabilite","ventes","statistiques"],faq:["Le solde est-il ma banque FiveM ?","Non. Il représente le journal financier RP enregistré dans Nyro Dashboard."]},
 audit:{purpose:"Le journal d’audit d’entreprise attribue les actions importantes à leur auteur et conserve leur contexte. Il aide à comprendre une correction ou une modification de droits sans effacer les opérations d’origine.",access:"Voir le journal d’audit est nécessaire. L’accès porte sur l’entreprise sélectionnée et ne donne aucun accès à un autre espace ou à des outils internes Nyro Dashboard.",setup:"Aucune connexion à un serveur FiveM n’est nécessaire. Sélectionnez la bonne entreprise ; les événements se créent lors des opérations métier prises en charge.",steps:["Ouvrez Historique et audit dans la navigation autorisée.","Filtrez l’action, l’auteur et les dates ; utilisez les pages pour parcourir tous les résultats.","Vérifiez auteur, date et libellé avant d’interpréter la modification.","Ouvrez Consulter pour les différences enregistrées ; exportez les résultats filtrés en CSV si nécessaire.","Si le contexte manque, transmettez la référence de l’opération à votre direction sans diffuser de contenu confidentiel."],features:["Événements attribués et datés.","Recherche et filtres serveur par auteur, action, identifiant et dates Paris.","Pagination de 25 événements, tri, détails autorisés avant/après et export CSV filtré jusqu’à 5 000 lignes."],example:"Après une erreur de stock, la direction retrouve le mouvement initial et la compensation motivée plutôt que de masquer l’écart.",limits:"Les comparaisons utilisent uniquement les champs enregistrés et autorisés : les anciens événements sans différence ne sont pas reconstruits. Notes RH, secrets et champs financiers non autorisés restent masqués. L’export est limité à 5 000 lignes ; affinez les filtres au-delà.",errors:["Action non retrouvée : vérifier entreprise et limites de la liste affichée.","Accès refusé : demander le droit de lecture approprié ; un lien partagé ne le remplace pas."],related:["permissions-entreprise","comptabilite","stocks"],faq:["Puis-je supprimer une entrée pour corriger une erreur ?","Le parcours utilisateur privilégie les corrections et compensations tracées ; le journal ne propose pas d’effacement libre."]},
};

const planned:Record<string,{detail:string;alternative:string;related:string[]}>={
 contracts:{detail:"Le stockage de base prévu pour les contrats ne constitue pas un module utilisateur. Création, modèles, approbations, signature RP, PDF et archivage dédié restent à développer.",alternative:"Les notes des autres modules peuvent décrire un contexte RP, mais elles ne constituent pas un contrat signé ni un accord bilatéral enregistré.",related:["documents","devis","partenaires"]},
 branches:{detail:"Les succursales ne sont pas livrées : établissements, responsables locaux, équipes et rapports propres à une branche restent à développer.",alternative:"Les entrepôts de Stocks gèrent des emplacements de quantité, pas des établissements ni des permissions par succursale.",related:["stocks","employes","changer-entreprise"]},
 automations:{detail:"Les modèles techniques de scénarios et de jobs ne sont pas un moteur d’automatisation opérationnel. Aucun éditeur de déclencheurs, action planifiée ou reprise automatique n’est exposé.",alternative:"Les règles immédiates intégrées aux modules continuent de fonctionner. Une annonce datée devient visible selon ses dates, sans promettre une notification programmée.",related:["annonces","calendrier","notifications"]},
 public:{detail:"La page publique Nyro Dashboard et l’annuaire de recrutement sont disponibles, mais un mini-site personnalisable propre à chaque entreprise ne l’est pas.",alternative:"Vous pouvez partager une offre de recrutement publiée. Ne publiez pas une URL privée de dossier comme si elle était une vitrine d’entreprise.",related:["recrutement","confidentialite","clients-crm"]},
 partners:{detail:"Aucun annuaire de partenaires avec accord bilatéral, documents partagés et livraison interentreprises n’est encore livré.",alternative:"Les fournisseurs et clients restent des fiches internes à chaque entreprise ; les créer ne donne aucun accès aux données de l’autre société.",related:["fournisseurs","clients-crm","contrats"]},
};

export function moduleGuide(meta:DocMeta):DocContent{
 const key=meta.module!,definition=modules.find(m=>m.key===key)!;
 const g=guides[key];
 if(!g){const p=planned[key];return {related:p.related,sections:[
  {id:"presentation",title:"Présentation et état actuel",paragraphs:[p.detail],callout:"En développement : aucune activation ni action dédiée n’est disponible dans cette version."},
  {id:"acces",title:"Qui peut l’utiliser ?",paragraphs:["Aucun grade ne peut activer une fonction qui n’est pas encore livrée. Un nom de module ou une table technique ne constitue pas une fonctionnalité disponible."]},
  {id:"navigation",title:"Où le retrouver ?",paragraphs:["Le catalogue Modules répertorie cette fonction avec son état. N’essayez pas de contourner cette indication avec une URL directe."],links:[{slug:"catalogue-modules",label:"Comprendre le catalogue et ses états"}]},
  {id:"configuration",title:"Configuration",paragraphs:["Il n’y a pas de réglage utilisateur de ce module à préparer aujourd’hui. Aucun script FiveM, paiement ou secret supplémentaire ne peut le rendre disponible."]},
  {id:"parcours",title:"Parcours actuellement utilisable",paragraphs:[p.alternative]},
  {id:"fonctionnalites",title:"Fonctionnalités et limites",paragraphs:[p.detail,"Les évolutions seront documentées lorsqu’un parcours réellement utilisable aura été livré. Aucun calendrier de sortie n’est annoncé ici."]},
  {id:"exemple",title:"Exemple Roleplay",example:p.alternative},
  {id:"relations",title:"Guides associés",links:p.related.map(slug=>({slug,label:slug.replaceAll("-"," ")}))},
  {id:"erreurs",title:"Éviter les confusions",items:["Un élément présent dans le catalogue peut être indisponible.","Les données d’un autre module ne deviennent pas partagées ou automatisées par simple mention de cette fonction.","Les droits et l’isolation des entreprises restent applicables aux alternatives existantes."]},
  {id:"questions",title:"Questions fréquentes",faq:[{question:"Puis-je demander une activation manuelle ?",answer:"Une activation ne remplace pas le développement du module. Consultez son état dans le catalogue."},{question:"Que faire en attendant ?",answer:p.alternative}]},
 ]};}
 const related=[...new Set(g.related)];
 return {related,sections:[
  {id:"presentation",title:"Présentation",paragraphs:[g.purpose],callout:`Disponible avec limites : ${g.limits}`},
  {id:"acces",title:"Qui peut l’utiliser ?",paragraphs:[g.access,`Accès principal du module : ${permissionLabels[definition.permission]??definition.permission}. L’entreprise, le compte et les modules nécessaires doivent être actifs.`]},
  {id:"navigation",title:"Comment y accéder ?",steps:["Connectez-vous avec Discord et choisissez un espace autorisé.","Sélectionnez l’entreprise concernée dans le sélecteur d’entreprise.",`Ouvrez « ${definition.name} » dans la navigation. Si ce lien manque, vérifiez le catalogue Modules et votre grade.`]},
  {id:"configuration",title:"Configuration",paragraphs:[g.setup,...(definition.dependencies.length?[`Modules associés à activer : ${definition.dependencies.map(k=>modules.find(m=>m.key===k)!.name).join(", ")}. Leur activation ne vous accorde pas automatiquement les permissions correspondantes.`]:[])]},
  {id:"tutoriel",title:"Tutoriel pas à pas",steps:g.steps},
  {id:"fonctionnalites",title:"Fonctionnalités disponibles",items:g.features,callout:g.limits},
  {id:"exemple",title:"Exemple Roleplay",example:g.example},
  {id:"relations",title:"Relations avec les autres modules",paragraphs:["Vérifiez les effets dans le module d’origine avant de recréer une opération manuellement. Un même règlement ne doit pas être saisi deux fois."],links:related.map(slug=>({slug,label:slug.replaceAll("-"," ")}))},
  {id:"erreurs",title:"Erreurs fréquentes",items:g.errors},
  {id:"questions",title:"Questions fréquentes",faq:[{question:g.faq[0],answer:g.faq[1]},{question:"Faut-il installer un script FiveM ?",answer:"Non. Les fonctions décrites sont utilisables depuis le navigateur. Nyro Dashboard n’exécute pas automatiquement d’actions dans le jeu."}]},
 ]};
}

export const moduleGuideCoverage=()=>modules.map(m=>({key:m.key,documented:!!moduleDoc(m.key),content:!!guides[m.key]||!!planned[m.key]}));
